export const STAGES=['Revisar','Selecionado','Contato feito','Conversando','Proposta enviada','Fechado','Sem interesse'];
export const NICHES={all:[['shop','.*'],['office','.*'],['craft','.*'],['amenity','restaurant|cafe|bar|fast_food|clinic|doctors|dentist|veterinary|pharmacy|car_wash|fuel|bank'],['tourism','hotel|guest_house|hostel']],beauty:[['shop','hairdresser|beauty|massage|cosmetics']],repair:[['shop','car_repair|car_parts|tyres|motorcycle_repair'],['amenity','car_wash']],food:[['amenity','restaurant|cafe|bar|fast_food|ice_cream'],['shop','bakery|confectionery']],health:[['amenity','clinic|doctors|dentist|pharmacy'],['healthcare','.*']],pet:[['shop','pet|pet_grooming'],['amenity','veterinary']],shop:[['shop','.*']],professional:[['office','.*'],['craft','.*']],stay:[['tourism','hotel|guest_house|hostel|motel']]};
export function fold(s){return String(s??'').normalize('NFD').replace(/\p{M}/gu,'').toLowerCase().trim();}
export function safeUrl(s){try{let v=String(s||'').trim();if(!v)return '';if(!/^[a-z][a-z\d+.-]*:/i.test(v))v='https://'+v;const u=new URL(v);return /^https?:$/.test(u.protocol)?u.href:'';}catch{return '';}}
export function phoneDigits(s){let raw=String(s||'').trim();if(/^https?:\/\//i.test(raw)){try{const u=new URL(raw);if(u.hostname==='wa.me')raw='+'+u.pathname.slice(1);else if(u.hostname==='api.whatsapp.com'||u.hostname==='www.whatsapp.com')raw='+'+(u.searchParams.get('phone')||'');else return '';}catch{return '';}}if(/[a-z]/i.test(raw))return '';let n=raw.split(/[;,]/)[0].replace(/\D/g,'');if(!raw.startsWith('+')&&(n.length===10||n.length===11))n='55'+n;return n.length>=10&&n.length<=15?n:'';}
export function distanceKm(a,b,c,d){const r=Math.PI/180,dx=(c-a)*r,dy=(d-b)*r;const v=Math.sin(dx/2)**2+Math.cos(a*r)*Math.cos(c*r)*Math.sin(dy/2)**2;return 6371*2*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)));}
export function queryFor(niche,lat,lon,radius){if(!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lon)||Math.abs(lon)>180||![3,5,10,20].includes(radius))throw new Error('Área inválida');const filters=NICHES[niche];if(!filters)throw new Error('Nicho inválido');return '[out:json][timeout:25];('+filters.map(([k,v])=>'nwr(around:'+radius*1000+','+lat+','+lon+')["'+k+'"~"^('+v+')$"]["name"];').join('')+');out tags center 600;';}
const SOCIAL=/^(www\.)?(instagram\.com|facebook\.com|fb\.com|wa\.me|api\.whatsapp\.com|linktr\.ee|tiktok\.com)(\/|$)/i;
export function normalizeElement(e,city){const t=e.tags||{},lat=Number(e.lat??e.center?.lat),lon=Number(e.lon??e.center?.lon);if(!t.name||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return null;
 const rawSite=safeUrl(t['contact:website']||t.website||t.url),site=rawSite&&!SOCIAL.test(new URL(rawSite).hostname+'/')?rawSite:'';
 let ig=t['contact:instagram']||t.instagram||'';if(!ig&&rawSite&&/instagram\.com\//i.test(rawSite))ig=rawSite;if(ig&&!ig.includes('/'))ig='https://www.instagram.com/'+ig.replace(/^@/,'');const instagram=safeUrl(ig);
 const phone=t['contact:phone']||t.phone||t['contact:mobile']||t.mobile||'',wa=t['contact:whatsapp']||t.whatsapp||'',waNumber=phoneDigits(wa||phone),phoneNumber=phoneDigits(phone);
 const address=[t['addr:street'],t['addr:housenumber']].filter(Boolean).join(', ')+ (t['addr:suburb']?' · '+t['addr:suburb']:'');
 return {id:'osm:'+e.type+':'+e.id,name:String(t.name).slice(0,300),lat,lon,city:city.name+' · '+city.uf,ddd:city.ddd,category:t['healthcare:speciality']||t.shop||t.amenity||t.office||t.craft||t.tourism||t.healthcare||'Negócio local',address:address||'Endereço não informado na fonte',website:site,instagram,phone:String(phone).slice(0,100),phoneNumber,whatsapp:waNumber?'https://wa.me/'+waNumber:'',whatsappConfirmed:!!wa&&!!waNumber,distance:distanceKm(city.lat,city.lon,lat,lon),sourceUrl:'https://www.openstreetmap.org/'+e.type+'/'+e.id,fetchedAt:new Date().toISOString()};}
export function uniqueLeads(leads){const out=[];for(const x of leads){if(!out.some(y=>x.id===y.id||(fold(x.name)===fold(y.name)&&distanceKm(x.lat,x.lon,y.lat,y.lon)<.075)))out.push(x);}return out;}
export function csvCell(v){let s=String(v??'');if(/^[\s\uFEFF]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function toCsv(leads){const header=['nome','cidade','categoria','endereco','site_informado','telefone','instagram','whatsapp','whatsapp_confirmado','etapa','verificacao_site','proximo_contato','notas','latitude','longitude','fonte_url','consultado_em','atribuicao','licenca'];const rows=leads.map(l=>[l.name,l.city,l.category,l.address,l.website,l.phone,l.instagram,l.whatsapp,l.whatsappConfirmed?'sim':'não',l.stage||'Revisar',l.verified||'unknown',l.followup||'',l.notes||'',l.lat,l.lon,l.sourceUrl,l.fetchedAt,'© colaboradores do OpenStreetMap','https://opendatacommons.org/licenses/odbl/1-0/']);return '\uFEFF'+[header,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n');}
export function validateBackup(data){if(!data||data.version!==1||!Array.isArray(data.leads)||data.leads.length>5000)throw new Error('Backup não reconhecido. Use um arquivo exportado pelo Prospecta.');return data.leads.map(l=>{if(!l||typeof l.name!=='string'||typeof l.id!=='string'||!/^osm:(node|way|relation):\d+$/.test(l.id)||typeof l.lat!=='number'||!Number.isFinite(l.lat)||Math.abs(l.lat)>90||typeof l.lon!=='number'||!Number.isFinite(l.lon)||Math.abs(l.lon)>180)throw new Error('Há registros inválidos no backup.');const text=(x,max=4000)=>String(x??'').slice(0,max);return {id:l.id,name:text(l.name,300),lat:l.lat,lon:l.lon,city:text(l.city,150),category:text(l.category,100),address:text(l.address,500),website:safeUrl(l.website),phone:text(l.phone,100),phoneNumber:phoneDigits(l.phoneNumber||l.phone),instagram:safeUrl(l.instagram),whatsapp:/^https:\/\/wa\.me\/\d{10,15}$/.test(l.whatsapp)?l.whatsapp:'',whatsappConfirmed:l.whatsappConfirmed===true,sourceUrl:'https://www.openstreetmap.org/'+l.id.split(':').slice(1).join('/'),fetchedAt:text(l.fetchedAt,40),distance:Number.isFinite(l.distance)?l.distance:0,stage:STAGES.includes(l.stage)?l.stage:'Revisar',verified:['unknown','missing','exists'].includes(l.verified)?l.verified:'unknown',followup:/^\d{4}-\d{2}-\d{2}$/.test(l.followup)?l.followup:'',notes:text(l.notes)};});}
